choose.when:
SELECT cdtype, codecd, codenm, remark, dspord, useyn FROM haba900t_tbl WHERE cdtype = #{cdtype}
AND useyn = 'Y'
ORDER BY dspord, codecd

mapper.select:
select a.pgmid, a.pgmnm, a.upmucd, c.codenm as upmunm, a.grpcd, b.grpnm, a.dspord, a.useyn from haaa800t_tbl a left outer join haaa810t_tbl b on a.upmucd = b.upmucd and a.grpcd = b.grpcd left outer join haba900t_tbl c on c.cdtype = '320' and a.upmucd = c.codecd where 1=1
and a.upmucd = #{upmucd}
and a.grpcd = #{grpcd}
and a.pgmnm like concat('%', #{pgmnm}, '%')
order by a.dspord

mapper.delete:
DELETE a, b, c, d
  FROM haaa800t_tbl a LEFT JOIN haba930t_tbl b
    ON b.cmpycd = #{cmpycd} and b.pgmid = #{pgmid}
       LEFT JOIN haba935t_tbl c ON c.cmpycd = #{cmpycd} and c.pgmid = #{pgmid}
       LEFT JOIN haba940t_tbl d ON d.cmpycd = #{cmpycd} and d.pgmid = #{pgmid}
 WHERE a.pgmid = #{pgmid}

mapper.select:
SELECT upmucd, grpcd, grpnm, dspord, useyn FROM haaa810t_tbl WHERE 1=1
AND upmucd = #{upmucd}
ORDER BY upmucd, dspord

mapper.delete:
DELETE a, b, c, d
  FROM haaa810t_tbl a LEFT JOIN haba930t_tbl b
    ON a.upmucd = b.upmucd AND a.grpcd = b.grpcd AND b.cmpycd = #{cmpycd}
       LEFT JOIN haba935t_tbl c ON a.upmucd = c.upmucd AND a.grpcd = c.grpcd AND c.cmpycd = #{cmpycd}
       LEFT JOIN haba940t_tbl d ON a.upmucd = d.upmucd AND a.grpcd = d.grpcd AND d.cmpycd = #{cmpycd}
 WHERE a.upmucd = #{upmucd} AND a.grpcd = #{grpcd}
